export const ADS_V2_ASSEMBLY_LEASE_MS = 5 * 60 * 1000
/** Carimbo do POST ao Creatomate sem id depois disto = ambíguo vencido → falha (nunca reenvio). */
export const ADS_V2_CREATOMATE_AMBIGUOUS_MS = 15 * 60 * 1000
